import { pushLogin, pushLogout } from './push'

import { computed, reactive } from 'vue'
import { createResource } from 'frappe-ui'
import router from '../router'
import { isNativeApp, setAuth, clearAuth, storedUser } from './mobile'

/**
 * Refresh `window.csrf_token` dengan token dari session yang sedang aktif.
 *
 * HTML di-render Jinja saat first fetch & embed CSRF token untuk session SAAT
 * ITU (mis. Guest). Setelah login, session di server berganti tapi
 * window.csrf_token masih token lama → semua POST berikutnya ditolak
 * CSRFTokenError. Endpoint GET (tidak butuh CSRF) untuk dapat token terkini.
 *
 * Mode native (token auth) tidak memakai cookie/CSRF → langsung berhenti.
 */
export async function refreshCsrfToken() {
	if (isNativeApp()) return
	try {
		const res = await fetch('/api/method/juragan.api.apicekunit.get_csrf_token', {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = await res.json()
		if (data && data.message) {
			window.csrf_token = data.message
		}
	} catch (e) {
		console.warn('CSRF refresh gagal:', e)
	}
}

export function sessionUser() {
	const cookies = Object.fromEntries(
		document.cookie
			.split('; ')
			.filter(Boolean)
			.map((c) => c.split('='))
			.map(([k, v]) => [k, decodeURIComponent(v ?? '')])
	)
	let _sessionUser = cookies.user_id
	if (!_sessionUser || _sessionUser === 'Guest') {
		_sessionUser = null
	}
	return _sessionUser
}

// Konversi berbagai bentuk error dari frappeRequest jadi pesan Indonesia
function friendlyLoginError(err) {
	if (!err) return 'Login gagal. Coba lagi.'
	const raw =
		err?.messages?.[0] || err?._error_message || err?.exc_type || err?.message || String(err)
	const text = String(raw).toLowerCase()
	if (
		text.includes('invalid login') ||
		text.includes('authenticationerror') ||
		text.includes('incorrect password') ||
		text.includes('user disabled')
	) {
		return 'Email atau kata sandi salah.'
	}
	if (text.includes('does not exist') || text.includes('not found')) {
		return 'Akun tidak ditemukan.'
	}
	if (text.includes('locked') || text.includes('try again later')) {
		return 'Akun terkunci sementara. Coba beberapa saat lagi.'
	}
	// Backend tidak terjangkau / response bukan JSON. Termasuk kasus bench mati:
	// proxy dev balas HTTP 500 body kosong → frappe-ui crash baca `error.exc`
	// ("Cannot read properties of undefined (reading 'exc')").
	if (
		text.includes('failed to fetch') ||
		text.includes('network') ||
		text.includes('load failed') ||
		text.includes('internal server error') ||
		text.includes("reading 'exc'") ||
		text.includes('reading "exc"')
	) {
		return 'Tidak dapat terhubung ke server. Pastikan bench/Frappe sedang berjalan.'
	}
	return raw || 'Login gagal. Coba lagi.'
}

// Resource login: mode native menukar email+password → token API (kebal ITP);
// mode web memakai login cookie Frappe seperti biasa.
const loginResource = isNativeApp()
	? createResource({
			url: 'juragan.api.portal.mobile_auth.login',
			method: 'POST',
			makeParams({ email, password }) {
				return { usr: email, pwd: password }
			},
			onSuccess(data) {
				// data = { user, full_name, api_key, api_secret }
				setAuth(data)
				session.user = data.user
				pushLogin(session.user)
				session.errorMessage = ''
				loginResource.reset()
				router.replace('/')
			},
			onError(err) {
				console.error('Login error:', err)
				session.errorMessage = friendlyLoginError(err)
			},
	  })
	: createResource({
			url: 'login',
			method: 'POST',
			makeParams({ email, password }) {
				return { usr: email, pwd: password }
			},
			async onSuccess(data) {
				session.user = sessionUser()
				pushLogin(session.user)
				session.errorMessage = ''
				loginResource.reset()
				// Refresh CSRF token sebelum redirect (lihat refreshCsrfToken).
				await refreshCsrfToken()
				const next = (data && data.default_route) || '/'
				router.replace(next)
			},
			onError(err) {
				console.error('Login error:', err)
				session.errorMessage = friendlyLoginError(err)
			},
	  })

const logoutResource = createResource({
	url: 'logout',
	method: 'POST',
	onSuccess() {
		session.user = sessionUser()
		session.errorMessage = ''
		router.replace({ name: 'Login' })
	},
})

export const session = reactive({
	login: loginResource,
	logout: logoutResource,
	/** Logout: native cukup hapus token lokal; web panggil endpoint logout cookie. */
	async doLogout() {
		await pushLogout()
		if (isNativeApp()) {
			clearAuth()
			session.user = null
			session.errorMessage = ''
			router.replace({ name: 'Login' })
			return
		}
		await refreshCsrfToken()
		await logoutResource.submit()
	},
	// Sumber user awal: native pakai user tersimpan (tanpa cookie), web dari cookie.
	user: isNativeApp() ? storedUser() : sessionUser(),
	errorMessage: '',
	isLoggedIn: computed(() => !!session.user),
})
