/* ===== Absensi (kartu Clock in di greeting card) — DINONAKTIFKAN SEMENTARA =====
 *
 * Fiturnya belum sempurna, jadi pemicu di UI dimatikan dulu. TIDAK ADA yang
 * dihapus: backend (juragan.api.portal.absensi), helper data/absensi.js, dan
 * seluruh logika di bawah tetap utuh.
 *
 * Cara mengaktifkan kembali:
 *   1. Buka comment blok ini
 *   2. Buka comment import getDeviceId/getPosition & notifyError/notifySuccess
 *      di bagian atas <script>
 *   3. Buka comment blok markup di <template> dan hapus versi statisnya
 *   4. Rebuild aset: cd home && npm run build
 *
 * Karyawan TIDAK dikirim dari sini: backend menurunkannya dari user yang login
 * lewat Master Karyawan.user_id, supaya seseorang tidak bisa mengabsenkan orang
 * lain. Klien hanya mengirim lokasi GPS + ID perangkat.

const absensiRes = createResource({
	url: 'juragan.api.portal.absensi.get_status_absensi',
	method: 'GET',
	auto: true,
})
const absensi = computed(() => absensiRes.data || null)
// Log terakhir hari ini = IN → sedang bekerja, tombol berubah jadi "Clock out".
const sedangMasuk = computed(() => !!absensi.value?.sedang_masuk)
// Akun belum ditautkan ke Master Karyawan → tombol dinonaktifkan.
const belumTertaut = computed(() => absensi.value?.tertaut === false)

// "2026-08-03 08:00:00" → "08:00"
function jam(dt) {
	return dt ? String(dt).slice(11, 16) : ''
}

const absensiText = computed(() => {
	const a = absensi.value
	if (!a) return "You haven't clocked in today."
	if (a.tertaut === false) return 'Akun Anda belum terhubung ke data karyawan.'
	if (a.sedang_masuk) return `Clock in pukul ${jam(a.waktu_masuk)}.`
	if (a.waktu_keluar) return `Clock in ${jam(a.waktu_masuk)} · Clock out ${jam(a.waktu_keluar)}.`
	return "You haven't clocked in today."
})

const clockInRes = createResource({
	url: 'juragan.api.portal.absensi.clock_in',
	method: 'POST',
})
const clockOutRes = createResource({
	url: 'juragan.api.portal.absensi.clock_out',
	method: 'POST',
})

const sedangAbsen = ref(false)
async function absen() {
	if (sedangAbsen.value || belumTertaut.value) return
	sedangAbsen.value = true
	try {
		// Lokasi dibaca DULU: bila izin GPS ditolak, tidak ada log yang tercatat
		// setengah jadi — backend juga menolak bila lat/long kosong.
		const pos = await getPosition()
		const payload = {
			latitude: pos.latitude,
			longitude: pos.longitude,
			id_perangkat: await getDeviceId(),
		}
		if (sedangMasuk.value) {
			await clockOutRes.submit(payload)
			notifySuccess('Clock out tercatat.')
		} else {
			await clockInRes.submit(payload)
			notifySuccess('Clock in tercatat.')
		}
		await absensiRes.reload()
	} catch (e) {
		notifyError(e, 'Gagal mencatat absensi')
	} finally {
		sedangAbsen.value = false
	}
}

===== akhir blok absensi ===== */

// Carousel ringkasan HANYA untuk role yang punya scope datanya. Isi & sumbernya
// berbeda per role:
