//   - CMO         → Ringkasan Pengajuan, stats marketing sendiri (get_cmo_stats)
// Role lain (Director/Administrator/dst) → null, carousel tidak dirender.
// Catatan urutan: cek *Coll* SEBELUM CMO/Pimcab agar role collection diutamakan.
const { roles, department, ready } = useRoleMenu()
const hasCollRole = computed(() => roles.value.some((r) => /coll/i.test(r)))

const statsConfig = computed(() => {
	if (hasCollRole.value)
		return {
			url: 'juragan.api.portal.home_stats.get_coll_stats',
			variant: 'collection',
			title: 'Ringkasan Target dan Realisasi',
		}
	if (department.value?.key === 'pimcab')
		return {
			url: 'juragan.api.portal.home_stats.get_pimcab_stats',
			variant: 'pengajuan',
			title: 'Ringkasan Pengajuan',
		}
	if (roles.value.includes('CMO'))
		return {
			url: 'juragan.api.portal.home_stats.get_cmo_stats',
			variant: 'pengajuan',
			title: 'Ringkasan Pengajuan',
		}
	return null
})

// Badge jumlah Workflow Requests (di ikon stempel kartu Workflow Requests).
const wfCountRes = createResource({
	url: 'juragan.api.portal.workflow_requests.get_workflow_requests_count',
	method: 'GET',
	auto: true,
})
const workflowCount = computed(() => wfCountRes.data || 0)

// Badge jumlah notifikasi belum dibaca (di ikon lonceng header).
// for_user difilter EKSPLISIT: scoping permission Notification Log dilewati
// untuk Administrator, sehingga tanpa filter ini admin melihat hitungan semua
// user. Menghitung notifikasi Data Pengajuan, SPPU Collector & Deviasi.
const notifCountRes = createResource({
	url: 'frappe.client.get_count',
	makeParams() {
		// Administrator → SEMUA notifikasi doctype terpilih milik semua user
		// (monitoring); user biasa → hanya miliknya (filter for_user eksplisit).
		const filters = [
			['read', '=', 0],
			['document_type', 'in', NOTIF_DOCTYPES],
		]
		// session.user, bukan sessionUser(): mode native (token auth) tidak punya
		// cookie user_id, jadi sessionUser() null → filter for_user='' → hitungan 0.
		const user = session.user
		if (user !== 'Administrator') filters.push(['for_user', '=', user || ''])
		return {
			doctype: 'Notification Log',
			filters: JSON.stringify(filters),
		}
	},
	auto: true,
})
const notifCount = computed(() => notifCountRes.data || 0)

// Refresh manual ringkasan: hanya memuat ulang data di dalam kartu (lewat method
// reload() yang di-expose StatsCarousel) — tanpa skeleton, tanpa reload halaman.
const statsCarousel = ref(null)
const refreshingStats = ref(false)
async function refreshStats() {
	if (refreshingStats.value) return
	refreshingStats.value = true
	try {
		await statsCarousel.value?.reload()
	} finally {
		refreshingStats.value = false
	}
}

// Tentukan halaman yang dibuka tiap menu lewat properti `route` (nama route di
