const M_DEVIASI = { name: 'deviasi', label: 'Deviasi', route: 'Deviasi' }
// BSTK — list card (halaman detail menyusul).
const M_BSTK = { name: 'bstk', label: 'BSTK', route: 'Bstk' }
// TTS — list card (halaman detail menyusul).
