const M_MOTOR_TARIKAN = { name: 'motor-tarikan', label: 'Motor Tarikan', route: 'MotorTarikan' }
// Stock Out Motor — list card (halaman detail menyusul).
const M_STOCKOUT_MOTOR = {
	name: 'stockout-motor',
