// Invoice Motor — list card (halaman detail menyusul).
const M_INVOICE_MOTOR = { name: 'invoice-motor', label: 'Invoice Motor', route: 'InvoiceMotor' }
// Tebus Motor Nasabah — list + create + detail (workflow Tebus Motor).
const M_TEBUS = { name: 'tebus', label: 'Tebus Motor Nasabah', route: 'TebusMotor' }
// Request AYDA Motor — list + create + detail (workflow Request AYDA Unit).
const M_AYDA = { name: 'ayda', label: 'Request AYDA Motor', route: 'RequestAyda' }
