const collMenu = computed(() => {
	const r = roles.value
	const items = [...MENU_COLL_BASE]
	if (r.includes('Manager Coll')) items.push(M_DEVIASI)
	if (r.includes('Field Coll') || r.includes('Desk Coll') || r.includes('Admin Coll')) {
		items.push(M_BSTK, M_TTS)
